class DuplicateKeyError(ValueError):
    """Raised when a JSON object repeats a key."""


@dataclass(frozen=True)
class LedgerValidation:
    """Validation result returned to tests and the command-line entry point."""

    errors: tuple[str, ...]
    machine_checked_completion: bool


@dataclass(frozen=True)
class ProductionTraceExtractionArtifactPaths:
    """Exact retained artifacts authenticated by the theorem certificate."""

    ledger: Path
    evidence: Path
    verus_evidence: Path
    verus_log: Path
    cross_tool_evidence: Path | None


@dataclass(frozen=True)
class RustItem:
    """One brace-delimited Rust or Verus function item."""

    name: str
    line: int
    source: str
    body: str
    structural_source: str
    brace_context: tuple[tuple[str, ...], ...]
    delimiter_context: tuple[tuple[str, int, tuple[str, ...]], ...]
    attributes: tuple[str, ...]
    ancestor_inner_attributes: tuple[str, ...]


@dataclass(frozen=True)
class RustStatement:
    """One semicolon-terminated statement at Rust file depth zero."""

    line: int
    source: str
    tokens: tuple[str, ...]
    ancestor_inner_attributes: tuple[str, ...]


def _unique_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise DuplicateKeyError(f"duplicate JSON key: {key}")
        result[key] = value
    return result


def load_ledger(path: Path = LEDGER_PATH) -> Any:
    """Load a ledger while rejecting duplicate JSON keys."""
    return json.loads(path.read_text(encoding="utf-8"), object_pairs_hook=_unique_object)


# One validation pass revisits every formal module through several independent
# fail-closed checks.  Keep the cache larger than the corridor's module count
# so those checks stay linear without retaining an unbounded number of mutated
# test fixtures.
@lru_cache(maxsize=64)
def strip_tla_comments(
    source: str, *, preserve_string_contents: bool = False
) -> str:
    """Remove TLA+ comments while preserving lines and, optionally, strings."""
    output: list[str] = []
    index = 0
    depth = 0
    in_string = False
    while index < len(source):
        pair = source[index : index + 2]
        char = source[index]
        if depth:
            if pair == "(*":
                depth += 1
                output.extend("  ")
                index += 2
                continue
            if pair == "*)":
                depth -= 1
                output.extend("  ")
                index += 2
                continue
            output.append("\n" if char == "\n" else " ")
            index += 1
            continue
        if in_string:
            if char == "\\" and index + 1 < len(source):
                escaped = source[index : index + 2]
                output.extend(
                    escaped
                    if preserve_string_contents
                    else tuple(
                        "\n" if escaped_char == "\n" else " "
                        for escaped_char in escaped
                    )
                )
                index += 2
                continue
            if pair == '\"\"':
                output.extend(pair if preserve_string_contents else "  ")
                index += 2
                continue
            if char == '\"':
                output.append(char)
                in_string = False
            else:
                output.append(
                    char
                    if preserve_string_contents
                    else ("\n" if char == "\n" else " ")
                )
            index += 1
            continue
        if pair == "(*":
            depth = 1
            output.extend("  ")
            index += 2
            continue
        if pair == "\\*":
            newline = source.find("\n", index)
            if newline == -1:
                output.extend(" " * (len(source) - index))
                break
            output.extend(" " * (newline - index))
            output.append("\n")
            index = newline + 1
            continue
        output.append(char)
        if char == '"':
            in_string = True
        index += 1
    return "".join(output)


def _rust_literal_end(source: str, start: int) -> int | None:
    """Return the exclusive end of a Rust string/character literal."""
    length = len(source)
    raw_marker: int | None = None
    if source.startswith(("br", "rb", "cr", "rc"), start):
        raw_marker = start + (1 if source[start] != "r" else 0)
    elif start < length and source[start] == "r":
        raw_marker = start
    if raw_marker is not None:
        quote = raw_marker + 1
        hashes = 0
        while quote + hashes < length and source[quote + hashes] == "#":
            hashes += 1
        opening_quote = quote + hashes
        if opening_quote >= length or source[opening_quote] != '"':
            return None
        terminator = '"' + ("#" * hashes)
        closing = source.find(terminator, opening_quote + 1)
        return None if closing < 0 else closing + len(terminator)
    quote = start + 1 if start < length and source[start] in "bc" else start
    if quote >= length or source[quote] != '"':
        return None
    index = quote + 1
    while index < length:
        char = source[index]
        if char == "\\":
            index += 2
            continue
        if char == '"':
            return index + 1
        index += 1
    return None


def _rust_char_literal_end(source: str, start: int) -> int | None:
    """Return a Rust char/byte-char end without mistaking lifetimes for chars."""
    length = len(source)
    quote = start + 1 if source.startswith("b'", start) else start
    if quote >= length or source[quote] != "'" or quote + 2 >= length:
        return None
    index = quote + 1
    if source[index] == "\\":
        index += 1
        if index >= length:
            return None
        if source[index] == "x":
            index += 3
        elif source[index] == "u" and index + 1 < length and source[index + 1] == "{":
            closing = source.find("}", index + 2)
            if closing < 0:
                return None
            index = closing + 1
        else:
            index += 1
    else:
        if source[index] in "'\n\r":
            return None
        index += 1
    return index + 1 if index < length and source[index] == "'" else None


@lru_cache(maxsize=32)
def mask_rust_comments_and_literals(source: str) -> str:
    """Mask Rust comments and literals while preserving byte offsets and lines.

    Rust block comments nest. Raw strings may use an arbitrary number of hash
    delimiters. Character handling intentionally recognizes only complete
    one-scalar/escaped literals, so lifetimes such as ``'a`` remain code.
    """
    output = list(source)
    def mask(start: int, end: int) -> None:
        for offset in range(start, end):
            if output[offset] != "\n":
                output[offset] = " "
    index = 0
    length = len(source)
    while index < length:
        if source.startswith("//", index):
            end = source.find("\n", index + 2)
            end = length if end < 0 else end
            mask(index, end)
            index = end
            continue
        if source.startswith("/*", index):
            depth = 1
            end = index + 2
            while end < length and depth:
                if source.startswith("/*", end):
                    depth += 1
                    end += 2
                elif source.startswith("*/", end):
                    depth -= 1
                    end += 2
                else:
                    end += 1
            mask(index, end)
            index = end
            continue
        literal_end = _rust_literal_end(source, index)
        if literal_end is None and (source[index] == "'" or source.startswith("b'", index)):
            literal_end = _rust_char_literal_end(source, index)
        if literal_end is not None:
            mask(index, literal_end)
            index = literal_end
            continue
        index += 1
    return "".join(output)


@lru_cache(maxsize=32)
def mask_rust_comments(source: str) -> str:
    """Mask Rust comments while preserving real literals and byte offsets."""
    output = list(source)
    def mask(start: int, end: int) -> None:
        for offset in range(start, end):
            if output[offset] != "\n":
                output[offset] = " "
    index = 0
    length = len(source)
    while index < length:
        literal_end = _rust_literal_end(source, index)
        if literal_end is None and (
            source[index] == "'" or source.startswith("b'", index)
        ):
            literal_end = _rust_char_literal_end(source, index)
        if literal_end is not None:
            index = literal_end
            continue
        if source.startswith("//", index):
            end = source.find("\n", index + 2)
            end = length if end < 0 else end
            mask(index, end)
            index = end
            continue
        if source.startswith("/*", index):
            depth = 1
            end = index + 2
            while end < length and depth:
                if source.startswith("/*", end):
                    depth += 1
                    end += 2
                elif source.startswith("*/", end):
                    depth -= 1
                    end += 2
                else:
                    end += 1
            mask(index, end)
            index = end
            continue
        index += 1
    return "".join(output)


_RUST_TOKEN_RE = re.compile(
    r"[A-Za-z_][A-Za-z0-9_]*|[0-9]+(?:_[0-9]+)*|"
    r"&&&|=~=|\.\.=|::|->|=>|==|!=|<=|>=|&&|\|\||\.\.|[^\s]"
)
_TLA_TOKEN_RE = re.compile(
    r"\\[A-Za-z]+|[A-Za-z_][A-Za-z0-9_]*|[0-9]+|"
    r"<=>|=>|~>|/\\|\\/|<<|>>|\[\]|==|/=|<=|>=|\.\.|[^\s]"
)

