@lru_cache(maxsize=512)
def rust_code_tokens(source: str) -> tuple[str, ...]:
    """Tokenize Rust/Verus structure after removing comments and literals."""
    return tuple(_RUST_TOKEN_RE.findall(mask_rust_comments_and_literals(source)))


@lru_cache(maxsize=1024)
def tla_code_tokens(source: str) -> tuple[str, ...]:
    """Tokenize executable TLA+ while excluding comments and string contents."""
    return tuple(_TLA_TOKEN_RE.findall(strip_tla_comments(source)))


def _rust_item_token_sha256(item: RustItem) -> str:
    """Hash one comment/literal-free item token stream unambiguously."""
    encoded = "\0".join(rust_code_tokens(item.source)).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _rust_sealed_item_token_sha256(item: RustItem) -> str:
    """Hash one item's declaration together with every leading attribute."""
    source = "\n".join((*item.attributes, item.source))
    encoded = "\0".join(rust_code_tokens(source)).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _rust_statement_token_sha256(statement: RustStatement) -> str:
    """Hash one exact top-level statement token stream unambiguously."""
    encoded = "\0".join(statement.tokens).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


@lru_cache(maxsize=512)
def _rust_delimiter_context(
    structural_source: str, end: int
) -> tuple[tuple[str, int, tuple[str, ...]], ...]:
    """Return every unmatched delimiter ancestor enclosing ``end``.

    Item extraction asks for the same context separately when binding brace,
    delimiter, and ancestor-attribute ownership. Cache that immutable parse so
    mutation-matrix validation does not rescan a large production file for
    each view of the same item.
    """
    stack: list[tuple[str, int, tuple[str, ...]]] = []
    matching = {')': '(', ']': '[', '}': '{'}
    last_boundary = 0
    for index, char in enumerate(structural_source[:end]):
        if char in "([{":
            stack.append(
                (
                    char,
                    index,
                    rust_code_tokens(structural_source[last_boundary:index]),
                )
            )
            if char == "{":
                last_boundary = index + 1
        elif char in ")]}":
            if stack and stack[-1][0] == matching[char]:
                stack.pop()
            else:
                stack.append((f"unmatched:{char}", index, ()))
            if char == "}":
                last_boundary = index + 1
        elif char == ";":
            last_boundary = index + 1
    return tuple(stack)


def _rust_brace_context(
    structural_source: str, end: int
) -> tuple[tuple[str, ...], ...]:
    """Return tokenized headers for curly-brace ancestors enclosing ``end``."""
    return tuple(
        header
        for opener, _position, header in _rust_delimiter_context(
            structural_source, end
        )
        if opener == "{"
    )


def _rust_attribute_end(structural_source: str, start: int) -> int:
    """Return the exclusive end of one bracketed Rust attribute."""
    opening = structural_source.find("[", start)
    if opening < 0:
        return start
    depth = 0
    for index in range(opening, len(structural_source)):
        if structural_source[index] == "[":
            depth += 1
        elif structural_source[index] == "]":
            depth -= 1
            if depth == 0:
                return index + 1
    return len(structural_source)


def _rust_ancestor_inner_cfg_attributes(
    source: str,
    structural_source: str,
    start: int,
    item_context: tuple[tuple[str, int, tuple[str, ...]], ...],
) -> tuple[str, ...]:
    """Collect file/ancestor inner attributes that can suppress an item."""
    item_positions = tuple(position for _opener, position, _header in item_context)
    attributes: list[str] = []
    pattern = re.compile(r"#\s*!\s*\[\s*cfg(?:_attr)?\b")
    for match in pattern.finditer(structural_source, 0, start):
        context = _rust_delimiter_context(structural_source, match.start())
        positions = tuple(position for _opener, position, _header in context)
        if positions != item_positions[: len(positions)]:
            continue
        end = _rust_attribute_end(structural_source, match.start())
        attribute = source[match.start() : end]
        tokens = rust_code_tokens(attribute)
        # `cfg_attr` is not inherently suppressive. First-release source modules
        # use it for lint-only `allow(dead_code)` annotations while keeping every
        # item compiled. Retain only direct `cfg` attributes or a `cfg_attr`
        # whose generated attribute is itself `cfg(...)`.
        if "cfg_attr" not in tokens or "cfg" in tokens:
            attributes.append(attribute)
    return tuple(attributes)


def _leading_rust_attributes(
    source: str, structural_source: str, start: int
) -> tuple[str, ...]:
    """Collect contiguous attributes immediately preceding an item."""
    attributes: list[str] = []
    cursor = start
    while True:
        while cursor > 0 and structural_source[cursor - 1].isspace():
            cursor -= 1
        if cursor == 0 or structural_source[cursor - 1] != "]":
            break
        depth = 1
        opening = cursor - 2
        while opening >= 0 and depth:
            if structural_source[opening] == "]":
                depth += 1
            elif structural_source[opening] == "[":
                depth -= 1
            opening -= 1
        if depth:
            break
        opening += 1
        hash_index = opening - 1
        if hash_index >= 0 and structural_source[hash_index] == "!":
            hash_index -= 1
        if hash_index < 0 or structural_source[hash_index] != "#":
            break
        attributes.append(source[hash_index:cursor])
        cursor = hash_index
    attributes.reverse()
    return tuple(attributes)


def _token_sequence_count(
    haystack: Sequence[str], needle: Sequence[str]
) -> int:
    """Count contiguous token sequences without accepting comment stuffing."""
    width = len(needle)
    if width == 0:
        return 0
    return sum(
        tuple(haystack[index : index + width]) == tuple(needle)
        for index in range(len(haystack) - width + 1)
    )


def _token_sequence_positions(
    haystack: Sequence[str], needle: Sequence[str]
) -> tuple[int, ...]:
    """Return exact contiguous-token offsets without accepting identifier joins."""
    width = len(needle)
    if width == 0:
        return ()
    return tuple(
        index
        for index in range(len(haystack) - width + 1)
        if tuple(haystack[index : index + width]) == tuple(needle)
    )


def _adapter_step_has_synchronous_reducer_effect_dataflow(source: str) -> bool:
    """Bind one reducer result directly to one later synchronous effect drive."""
    tokens = rust_code_tokens(source)
    outcome = _token_sequence_positions(tokens, ("let", "outcome", "="))
    reducer = _token_sequence_positions(tokens, rust_code_tokens("self.step_reducer(event)"))
    drive = _token_sequence_positions(
        tokens, rust_code_tokens("self.drive_effects(outcome.into_effects())")
    )
    if len(outcome) != 1 or len(reducer) != 1 or len(drive) != 1:
        return False
    binding = tuple(tokens[outcome[0] + 3 : reducer[0]])
    return binding in ((), ("match",)) and reducer[0] < drive[0]


def _tla_dependency_positions(
    proof: str, dependency: str
) -> tuple[int, ...]:
    """Locate a reviewed TLA+ dependency as an exact code-token sequence."""
    return _token_sequence_positions(
        tla_code_tokens(proof),
        tla_code_tokens(dependency),
    )


def _tla_dependency_present(proof: str, dependency: str) -> bool:
    """Reject dependency names hidden in comments, strings, or larger identifiers."""
    return bool(_tla_dependency_positions(proof, dependency))


def rust_items(source: str, name: str) -> tuple[RustItem, ...]:
    """Extract all real Rust/Verus function items named ``name``."""
    structural = mask_rust_comments_and_literals(source)
    declaration = re.compile(
        rf"(?m)^[ \t]*(?:pub(?:\s*\([^\n)]*\))?[ \t]+)?"
        rf"(?:(?:async|const)[ \t]+)*"
        rf"(?:(?:open|closed|broadcast|tracked|exec|spec|proof)[ \t]+)*"
        rf"fn[ \t]+{re.escape(name)}\b"
    )
    items: list[RustItem] = []
    for match in declaration.finditer(structural):
        paren_depth = 0
        bracket_depth = 0
        body_start = -1
        for index in range(match.end(), len(structural)):
            char = structural[index]
            if char == "(":
                paren_depth += 1
            elif char == ")":
                paren_depth = max(0, paren_depth - 1)
            elif char == "[":
                bracket_depth += 1
            elif char == "]":
                bracket_depth = max(0, bracket_depth - 1)
            elif char == "{" and paren_depth == 0 and bracket_depth == 0:
                body_start = index
                break
            elif char == ";" and paren_depth == 0 and bracket_depth == 0:
                break
        if body_start < 0:
            continue
        depth = 0
        body_end = -1
        for index in range(body_start, len(structural)):
            if structural[index] == "{":
                depth += 1
            elif structural[index] == "}":
                depth -= 1
                if depth == 0:
                    body_end = index + 1
                    break
        if body_end < 0:
            continue
        start = match.start()
        item_source = source[start:body_end]
        delimiter_context = _rust_delimiter_context(structural, start)
        items.append(
            RustItem(
                name=name,
                line=source.count("\n", 0, start) + 1,
                source=item_source,
                body=source[body_start + 1 : body_end - 1],
                structural_source=structural[start:body_end],
                brace_context=_rust_brace_context(structural, start),
                delimiter_context=delimiter_context,
                attributes=_leading_rust_attributes(source, structural, start),
                ancestor_inner_attributes=_rust_ancestor_inner_cfg_attributes(
                    source,
                    structural,
                    start,
                    delimiter_context,
                ),
            )
        )
    return tuple(items)


def rust_function_items_from_structural(
    source: str, structural: str, name: str
) -> tuple[RustItem, ...]:
    """Extract named real functions from one already-masked large source.

    Unlike :func:`rust_items`, this bounded helper intentionally omits enclosing-impl context.
    It is used when several unique functions must be inspected in a multi-megabyte source: the
    caller masks comments/literals once, and only the small selected item bodies are tokenized.
    """
    if len(source) != len(structural):
        raise ValueError("Rust structural source must preserve byte positions")
    declaration = re.compile(
        rf"(?m)^[ \t]*(?:pub(?:\s*\([^\n)]*\))?[ \t]+)?"
        rf"(?:(?:async|const)[ \t]+)*"
        rf"(?:(?:open|closed|broadcast|tracked|exec|spec|proof)[ \t]+)*"
        rf"fn[ \t]+{re.escape(name)}\b"
    )
    items: list[RustItem] = []
    for match in declaration.finditer(structural):
        paren_depth = 0
        bracket_depth = 0
        body_start = -1
        for index in range(match.end(), len(structural)):
            char = structural[index]
            if char == "(":
                paren_depth += 1
            elif char == ")":
                paren_depth = max(0, paren_depth - 1)
            elif char == "[":
                bracket_depth += 1
            elif char == "]":
                bracket_depth = max(0, bracket_depth - 1)
            elif char == "{" and paren_depth == 0 and bracket_depth == 0:
                body_start = index
                break
            elif char == ";" and paren_depth == 0 and bracket_depth == 0:
                break
        if body_start < 0:
            continue
        depth = 0
        body_end = -1
        for index in range(body_start, len(structural)):
            if structural[index] == "{":
                depth += 1
            elif structural[index] == "}":
                depth -= 1
                if depth == 0:
                    body_end = index + 1
                    break
        if body_end < 0:
            continue
        start = match.start()
        items.append(
            RustItem(
                name=name,
                line=source.count("\n", 0, start) + 1,
                source=source[start:body_end],
                body=source[body_start + 1 : body_end - 1],
                structural_source=structural[start:body_end],
                brace_context=(),
                delimiter_context=(),
                attributes=(),
                ancestor_inner_attributes=(),
            )
        )
    return tuple(items)


def _rust_all_function_items(
    source: str,
    *,
    references: Sequence[str] = (),
) -> tuple[RustItem, ...]:
    """Extract real Rust/Verus functions, optionally only reference-bearing ones.

    The exhaustive cross-tool inventory needs enclosing test/production context
    only for functions which actually invoke a reviewed gate, kernel, or linked
    helper.  Avoiding context reconstruction for every unrelated function keeps
    large production modules linear enough for the aggregate release checker.
    """
    structural = mask_rust_comments_and_literals(source)
    reference_pattern = (
        re.compile(
            r"\b(?:"
            + "|".join(re.escape(reference) for reference in references)
            + r")\s*\("
        )
        if references
        else None
    )
    declaration = re.compile(
        r"(?m)^[ \t]*(?:pub(?:\s*\([^\n)]*\))?[ \t]+)?"
        r"(?:(?:async|const)[ \t]+)*"
        r"(?:(?:open|closed|broadcast|tracked|exec|spec|proof)[ \t]+)*"
        r"fn[ \t]+([A-Za-z_][A-Za-z0-9_]*)\b"
    )
    items: list[RustItem] = []
    for match in declaration.finditer(structural):
        paren_depth = 0
        bracket_depth = 0
        body_start = -1
        for index in range(match.end(), len(structural)):
            character = structural[index]
            if character == "(":
                paren_depth += 1
            elif character == ")":
                paren_depth = max(0, paren_depth - 1)
            elif character == "[":
                bracket_depth += 1
            elif character == "]":
                bracket_depth = max(0, bracket_depth - 1)
            elif (
                character == "{"
                and paren_depth == 0
                and bracket_depth == 0
            ):
                body_start = index
                break
            elif (
                character == ";"
                and paren_depth == 0
                and bracket_depth == 0
            ):
                break
        if body_start < 0:
            continue
        depth = 0
        body_end = -1
        for index in range(body_start, len(structural)):
            if structural[index] == "{":
                depth += 1
            elif structural[index] == "}":
                depth -= 1
                if depth == 0:
                    body_end = index + 1
                    break
        if body_end < 0:
            continue
        if (
            reference_pattern is not None
            and reference_pattern.search(
                structural[body_start + 1 : body_end - 1]
            )
            is None
        ):
            continue
        start = match.start()
        delimiter_context = _rust_delimiter_context(structural, start)
        items.append(
            RustItem(
                name=match.group(1),
                line=source.count("\n", 0, start) + 1,
                source=source[start:body_end],
                body=source[body_start + 1 : body_end - 1],
                structural_source=structural[start:body_end],
                brace_context=_rust_brace_context(structural, start),
                delimiter_context=delimiter_context,
                attributes=_leading_rust_attributes(source, structural, start),
                ancestor_inner_attributes=_rust_ancestor_inner_cfg_attributes(
                    source,
                    structural,
                    start,
                    delimiter_context,
                ),
            )
        )
    return tuple(items)


def _rust_item_is_test_only(item: RustItem) -> bool:
    """Return whether an extracted function is enclosed by a test/bench gate."""
    context_tokens = tuple(
        token for header in item.brace_context for token in header
    )
    attribute_tokens = tuple(
        token
        for attribute in (*item.attributes, *item.ancestor_inner_attributes)
        for token in rust_code_tokens(attribute)
    )
    return bool({"test", "tests", "bench", "benches"} & set(
        (*context_tokens, *attribute_tokens)
    ))


def rust_struct_items(source: str, name: str) -> tuple[RustItem, ...]:
    """Extract all real brace-delimited Rust/Verus structs named ``name``."""
    structural = mask_rust_comments_and_literals(source)
    declaration = re.compile(
        rf"(?m)^[ \t]*(?:pub(?:\s*\([^\n)]*\))?[ \t]+)?"
        rf"struct[ \t]+{re.escape(name)}\b"
    )
    items: list[RustItem] = []
    for match in declaration.finditer(structural):
        body_start = structural.find("{", match.end())
        if body_start < 0:
            continue
        semicolon = structural.find(";", match.end(), body_start)
        if semicolon >= 0:
            continue
        depth = 0
        body_end = -1
        for index in range(body_start, len(structural)):
            if structural[index] == "{":
                depth += 1
            elif structural[index] == "}":
                depth -= 1
                if depth == 0:
                    body_end = index + 1
                    break
        if body_end < 0:
            continue
        start = match.start()
        delimiter_context = _rust_delimiter_context(structural, start)
        items.append(
            RustItem(
                name=name,
                line=source.count("\n", 0, start) + 1,
                source=source[start:body_end],
                body=source[body_start + 1 : body_end - 1],
                structural_source=structural[start:body_end],
                brace_context=_rust_brace_context(structural, start),
                delimiter_context=delimiter_context,
                attributes=_leading_rust_attributes(source, structural, start),
                ancestor_inner_attributes=_rust_ancestor_inner_cfg_attributes(
                    source,
                    structural,
                    start,
                    delimiter_context,
                ),
            )
        )
    return tuple(items)


