            "AsyncProgressOwnershipInvariant",
            "AsyncCandidateServiceLifecycleInvariant",
            "AdequateLeaderFrozenTargetCorridor",
            "AdequateLeaderTargetProducerContinuationRetiredOwnerIdentitySet",
            "AsyncNext",
