        reset_scalar_unchanged = set(
            re.findall(
                r"\bUNCHANGED\s+([A-Za-z][A-Za-z0-9_]*)\b",
                reset_scheduler[0],
            )
        )
        reset_constrained = (
            reset_writes | reset_unchanged | reset_scalar_unchanged
        )
